// =====================================================
// NUT 2: CAU HINH NGUONG PHAT HIEN TASK BI KET
// =====================================================
return [{
  json: {
    stuck_threshold_hours:    24,   // Task bi coi la "ket" sau 24 gio khong cap nhat
    critical_threshold_hours: 48,   // Task bi coi la "nguy hiem" sau 48 gio
    watch_threshold_hours:    12,   // Task can theo doi sau 12 gio
    statuses_to_check:        ['IN_PROGRESS', 'IN_REVIEW'],
    default_project_id:       'a0000001-0000-0000-0000-000000000001',
    checked_at:               new Date().toISOString(),
    flow_version:             'flow6_v1'
  }
}];

// =====================================================
// NUT 4: TONG HOP KET QUA VA PHAN LOAI MUC DO
// =====================================================
const allItems = $input.all();
const config   = $('Code - Set Alert Config').first().json;

// Loc ra cac dong co du lieu hop le tu Postgres
const tasks = allItems
  .filter(item => item.json && item.json.id)
  .map(item => ({
    ...item.json,
    hours_since_update: parseFloat(item.json.hours_since_update || 0)
  }));

if (tasks.length === 0) {
  return [{
    json: {
      has_stuck_tasks:  false,
      stuck_count:      0,
      critical_count:   0,
      warning_count:    0,
      watch_count:      0,
      risk_score:       0,
      tasks:            [],
      critical_tasks:   [],
      warning_tasks:    [],
      first_project_id: config.default_project_id,
      checked_at:       config.checked_at
    }
  }];
}

// Phan loai theo muc do
const critical = tasks.filter(t => t.hours_since_update >= config.critical_threshold_hours);
const warning  = tasks.filter(t => t.hours_since_update >= config.stuck_threshold_hours && t.hours_since_update < config.critical_threshold_hours);
const watch    = tasks.filter(t => t.hours_since_update >= config.watch_threshold_hours && t.hours_since_update < config.stuck_threshold_hours);

// Tinh diem rui ro (0-100)
const riskScore = Math.min(100, Math.round(
  critical.length * 30 + warning.length * 15 + watch.length * 5
));

return [{
  json: {
    has_stuck_tasks:  true,
    stuck_count:      tasks.length,
    critical_count:   critical.length,
    warning_count:    warning.length,
    watch_count:      watch.length,
    risk_score:       riskScore,
    tasks:            tasks,
    critical_tasks:   critical,
    warning_tasks:    warning,
    task_ids:         tasks.map(t => t.id),
    first_project_id: tasks[0].project_id || config.default_project_id,
    checked_at:       config.checked_at
  }
}];

// =====================================================
// NUT 6: LOG KHI KHONG CO TASK BI KET (ALL CLEAR)
// =====================================================
const config = $('Code - Set Alert Config').first().json;

return [{
  json: {
    all_clear:    true,
    message:      'Tat ca task dang hoat dong binh thuong. Khong phat hien task bi ket qua ' + config.stuck_threshold_hours + ' gio.',
    checked_at:   config.checked_at,
    flow:         'flow6-stuck-task-alert',
    risk_score:   0
  }
}];

// =====================================================
// NUT 10: CHUAN BI DU LIEU BAO CAO
// =====================================================
const data   = $('Code - Aggregate and Classify').first().json;
const config = $('Code - Set Alert Config').first().json;

// Tao danh sach task bi ket (loai bo ky tu dac biet de tranh loi SQL)
const cleanTitle = (str) => (str || 'Khong ro').replace(/['"\\]/g, '');

const stuckList = data.tasks.slice(0, 8).map(t =>
  '- ' + cleanTitle(t.assignee_name || 'Chua phan cong') +
  ': [' + t.status + '] ' + cleanTitle(t.title) +
  ' (bi ket ' + Math.round(t.hours_since_update) + 'h)'
).join(' | ');

const summaryText =
  'Flow6 Stuck Alert - Ket qua quet luc ' + data.checked_at +
  ' | Tong task bi ket: ' + data.stuck_count +
  ' | CRITICAL(>48h): ' + data.critical_count +
  ' | WARNING(24-48h): ' + data.warning_count +
  ' | Diem rui ro: ' + data.risk_score + '/100' +
  (stuckList ? ' | Chi tiet: ' + stuckList : '');

return [{
  json: {
    ...data,
    ai_summary: summaryText,
    metrics: {
      stuck_count:    data.stuck_count,
      critical_count: data.critical_count,
      warning_count:  data.warning_count,
      watch_count:    data.watch_count,
      risk_score:     data.risk_score,
      checked_at:     data.checked_at,
      flow:           'flow6_stuck_task_alert'
    }
  }
}];

// =====================================================
// NUT 12: FORMAT CANH BAO NGHIEM TRONG (CRITICAL)
// =====================================================
const data   = $input.first().json;
const config = $('Code - Set Alert Config').first().json;

const cleanTitle = (str) => (str || 'N/A').replace(/['"\\]/g, '');

const criticalDetail = data.critical_tasks.slice(0, 5).map(t =>
  'CRITICAL | ' + cleanTitle(t.assignee_name || 'Chua phan cong') +
  ' | ' + cleanTitle(t.title) +
  ' | Bi ket: ' + Math.round(t.hours_since_update) + 'h' +
  ' | Du an: ' + cleanTitle(t.project_name || 'N/A')
).join(' ;; ');

return [{
  json: {
    alert_level:      'CRITICAL',
    alert_message:    'CANH BAO NGHIEM TRONG: Co ' + data.critical_count +
                      ' task bi ket qua ' + config.critical_threshold_hours + ' gio!',
    risk_score:       data.risk_score,
    ai_summary:       data.ai_summary + ' [ALERT: CRITICAL tasks: ' + criticalDetail + ']',
    metrics:          data.metrics,
    first_project_id: data.first_project_id,
    stuck_count:      data.stuck_count,
    processed_at:     new Date().toISOString()
  }
}];

// =====================================================
// NUT 13: FORMAT CANH BAO CHUAN (WARNING)
// =====================================================
const data   = $input.first().json;
const config = $('Code - Set Alert Config').first().json;

return [{
  json: {
    alert_level:      'WARNING',
    alert_message:    'CANH BAO: Co ' + data.stuck_count +
                      ' task chua duoc cap nhat qua ' + config.stuck_threshold_hours + ' gio. Kiem tra tien do!',
    risk_score:       data.risk_score,
    ai_summary:       data.ai_summary,
    metrics:          data.metrics,
    first_project_id: data.first_project_id,
    stuck_count:      data.stuck_count,
    processed_at:     new Date().toISOString()
  }
}];
